function toBsonType(sqlType) {
  const t = sqlType.toLowerCase();
  if (t.startsWith('uuid')) return 'string';
  if (t.startsWith('varchar') || t.startsWith('text') || t.startsWith('char')) return 'string';
  if (t.startsWith('boolean') || t.startsWith('bool')) return 'bool';
  if (t.startsWith('int') || t.startsWith('smallint') || t.startsWith('bigint')) return 'number';
  if (t.startsWith('float') || t.startsWith('double') || t.startsWith('numeric') || t.startsWith('decimal') || t.startsWith('real')) return 'number';
  if (t.startsWith('timestamptz') || t.startsWith('timestamp') || t.startsWith('date')) return 'date';
  if (t.startsWith('time')) return 'string'; // store time-only values as HH:mm:ss strings
  return 'string';
}

for (const collection of collections) {
  const properties = { _id: { bsonType: 'string', description: 'SQL UUID primary key represented as a string' } };
  const required = ['_id'];
  for (const column of collection.columns) {
    const field = column.name === 'id' ? '_id' : column.name;
    if (field === '_id') continue;
    const bsonType = toBsonType(column.type);
    properties[field] = column.required
      ? { bsonType }
      : { bsonType: [bsonType, 'null'] };
    if (column.required) required.push(field);
  }
  // Optional denormalized snapshots reduce repeated lookups for common trip/booking screens.
  // The application should populate and maintain these snapshots when creating/updating records.
  if (collection.name === 'trips') {
    properties.route_snapshot = { bsonType: ['object', 'null'], properties: { origin_name: { bsonType: 'string' }, destination_name: { bsonType: 'string' }, distance_km: { bsonType: ['number', 'null'] }, est_minutes: { bsonType: ['number', 'null'] } }, additionalProperties: true };
    properties.bus_snapshot = { bsonType: ['object', 'null'], properties: { plate_number: { bsonType: 'string' }, model: { bsonType: ['string', 'null'] }, total_seats: { bsonType: ['number', 'null'] }, company_name: { bsonType: ['string', 'null'] } }, additionalProperties: true };
  }
  if (collection.name === 'bookings') {
    properties.trip_snapshot = { bsonType: ['object', 'null'], properties: { departure_time: { bsonType: ['date', 'null'] }, arrival_time: { bsonType: ['date', 'null'] }, origin_name: { bsonType: ['string', 'null'] }, destination_name: { bsonType: ['string', 'null'] }, bus_model: { bsonType: ['string', 'null'] }, company_name: { bsonType: ['string', 'null'] } }, additionalProperties: true };
    properties.seat_summary = { bsonType: ['array', 'null'], items: { bsonType: 'object', properties: { bus_seat_id: { bsonType: 'string' }, seat_number: { bsonType: 'string' }, passenger_name: { bsonType: ['string', 'null'] } }, additionalProperties: true } };
  }
  const validator = { $jsonSchema: { bsonType: 'object', required, properties, additionalProperties: true } };
  if (!db.getCollectionNames().includes(collection.name)) {
    db.createCollection(collection.name, { validator, validationLevel: 'moderate', validationAction: 'error' });
    print(`Created collection: ${collection.name}`);
  } else {
    db.runCommand({ collMod: collection.name, validator, validationLevel: 'moderate', validationAction: 'error' });
    print(`Updated validator: ${collection.name}`);
  }
}

// Unique constraints from SQL (including compound unique indexes).
for (const [collectionName, indexes] of Object.entries(uniqueIndexes)) {
  for (const index of indexes) {
    const mapped = {};
    for (const [field, direction] of Object.entries(index)) mapped[field === 'id' ? '_id' : field] = direction;
    db.getCollection(collectionName).createIndex(mapped, { unique: true, name: 'uq_' + Object.keys(mapped).join('_') });
  }
}

// Index foreign-key fields to support lookups/joins in application queries.
// These indexes do not enforce referential integrity.
for (const [collectionName, indexes] of Object.entries(referenceIndexes)) {
  for (const index of indexes) {
    db.getCollection(collectionName).createIndex(index, { name: 'ref_' + Object.keys(index).join('_') });
  }
}

// Query-oriented indexes for common app screens.
db.trips.createIndex({ departure_time: 1, status: 1 }, { name: 'idx_trips_departure_status' });
db.bookings.createIndex({ user_id: 1, booked_at: -1 }, { name: 'idx_bookings_user_date' });
db.bookings.createIndex({ trip_id: 1, status: 1 }, { name: 'idx_bookings_trip_status' });
db.bus_locations.createIndex({ trip_id: 1, recorded_at: -1 }, { name: 'idx_bus_locations_trip_time' });
db.notifications.createIndex({ user_id: 1, is_read: 1, created_at: -1 }, { name: 'idx_notifications_user_read_date' });

// Automatically remove expired seat-lock documents. TTL cleanup is asynchronous;
// application code must still check expires_at and handle concurrent seat booking safely.
db.trip_seat_locks.createIndex({ expires_at: 1 }, { expireAfterSeconds: 0, name: 'ttl_trip_seat_locks_expiry' });

print(`Optimized MongoDB schema setup complete for ${collections.length} collections.`);